          if (!g) ko.push(key + ' : #grenN absent'); else if (!/ESQUIVE/.test(esq) || !/SPRINT/.test(spr)) ko.push(key + ' : boutons « ' + esq.trim() + ' / ' + spr.trim() + ' »');
