      out.accOk = Math.abs(v.def.acc - base.acc * TUNING_EFFETS.moteur[slot.moteur]) < 1e-9;
      out.vehdefsIntact = VEHDEFS.pickup === base && base.vmax === VEHDEFS.pickup.vmax;
      out.nitro = v.nitro === true;
