        const s1 = saut(true), s2 = saut(true), s3 = saut(false);
        if (s1.erreur || s1.mort || !(s1.d < 3) || s1.prime <= 0) o.ko.push('saut sous voile : ' + JSON.stringify(s1));
        if (s2.mort || s2.prime !== 0) o.ko.push('second saut, même vague : ' + JSON.stringify(s2));
