        while (WANTED.heat > 0 && t < 30) { for (const e of ennemis) if (e.fac === 'police') e.mort = true; majWanted(1 / 30); t += 1 / 30; }
        if (!(t < 16)) ko.push('2★ retombent en ' + t.toFixed(1) + ' s');
        info.push('2★ effacées en ' + t.toFixed(1) + ' s');
