            P.x = v.x; P.z = v.z; entrerVehicule(v); if (P.veh !== v) { ko.push('on ne monte pas sur ' + v.key); continue; } const x0 = v.x, z0 = v.z; for (let i = 0; i < 120; i++) majVehiculePhys(v, 1 / 60, 0.5, 0, false);
