        const dans = brule(m[0], m[1]), aCote = brule(m[0] + 8, m[1] - 3);
        if (!(dans > 20) || aCote > 0) ko.push('lave : ' + dans + ' de dégâts dedans, ' + aCote + ' à côté'); else info.push('la lave brûle (' + dans + ' en 2 s)');
