        const vis = VOLCAN.panaches[0].sp.filter((q) => q.s.visible).length; if (vis < 5) ko.push('panache : ' + vis + ' bouffées'); else info.push(vis + ' bouffées de fumée');
        startRun(); P.hp = P.maxHp = 1e6;
