          if (Math.abs(d.long - Pf.L) > 0.01 || Math.abs(d.larg - Pf.W) > 0.01) ko.push(k + ' : profil ' + Pf.L + '×' + Pf.W + ' ≠ VEHDEFS ' + d.long + '×' + d.larg);
