        { const j = creerVehicule('jeep', 60, 40, 0, null); P.x = j.x; P.z = j.z; entrerVehicule(j); if (!P.h.g.visible || P.h.g.parent !== j.mesh) ko.push('joueur invisible dans le 4x4'); sortirVehicule(true); }
