          if (!(nezAv > 0.15 && vAv > 8)) ko.push(n + ' : en avançant, nez ' + nezAv.toFixed(2) + ', vitesse ' + vAv.toFixed(1));
          // virer : roulis du côté du virage (vers la gauche : roulis négatif)
