          let raides = 0; for (let i = 1; i < se.pts.length; i++) { const [x0, z0] = se.pts[i - 1], [x1, z1] = se.pts[i]; if (Math.abs(H(x1, z1) - H(x0, z0)) / (Math.hypot(x1 - x0, z1 - z0) || 1) > PENTE_MAX_PIED) raides++; }
