        const point = (s) => { s = clamp(s, 0, Ltot); let i = 1; while (i < T.length - 1 && cumul[i] < s) i++; const t = (s - cumul[i - 1]) / ((cumul[i] - cumul[i - 1]) || 1); return [T[i - 1][0] + (T[i][0] - T[i - 1][0]) * t, T[i - 1][1] + (T[i][1] - T[i - 1][1]) * t]; };
