          for (let i = 0; i < 30 * 10; i++) majTour(1 / 30); TOUR.vent.de += Math.PI; TOUR.vent.kt = 15; const arr = TOUR.avions.find((a) => a.type === 'arr' && !a.urg); toucher(arr); let tt = 0; while (TOUR.actif && tt < 30 && !TOUR.remises) { majTour(1 / 30); tt += 1 / 30; }
